"""Create and execute the results notebook from preserved experiment artifacts.
Usage: .venv/bin/python notebooks/build_notebook.py --run avaliacao/runs/test-v1
"""
from pathlib import Path
import argparse
import nbformat
from nbclient import NotebookClient
from nbconvert import HTMLExporter
ROOT=Path(__file__).resolve().parents[1]

def main(args):
    run=Path(args.run)
    if run.is_absolute(): run=run.relative_to(ROOT)
    if not (ROOT/run/'scoreboard.json').exists(): raise SystemExit('Run experiment first; notebook will not invent results.')
    n=nbformat.v4.new_notebook()
    n.metadata={'kernelspec':{'name':'python3','display_name':'Python 3','language':'python'},'language_info':{'name':'python','version':'3.12'},'ponto_certo':{'evidence_run':str(run),'purpose':'Executed experiment report; inputs remain versioned.'}}
    md=nbformat.v4.new_markdown_cell; code=nbformat.v4.new_code_cell
    n.cells=[
      md('# Ponto Certo · experimento de IA local\n\nComparação reproduzível entre o mesmo modelo **sem contexto**, **RAG simples** e **RAG + agente**. Global Solution CitizenTech 2026.2 · Generative AI for Engineering.\n\nEste notebook recalcula e apresenta as saídas preservadas. Para gerar novas respostas do modelo, execute `python -m avaliacao.run` seguindo o README. As previsões desta avaliação usam **dados sintéticos**, nunca uma consulta ao vivo.'),
      md('## Resumo dos resultados\n\nOs valores abaixo vêm do experimento salvo. Acerto por propriedades não equivale a acurácia semântica plena. JSON final e JSON bruto são medidas distintas.'),
      code("from pathlib import Path\nimport json, hashlib, statistics\nfrom IPython.display import display, Markdown\nimport matplotlib.pyplot as plt\nROOT = Path.cwd()\nif not (ROOT / 'avaliacao').exists(): ROOT = ROOT.parent\nRUN = ROOT / "+repr(str(run))+"\nrows = [json.loads(x) for x in (RUN / 'responses.jsonl').read_text().splitlines()]\nmanifest = json.loads((RUN / 'manifest.json').read_text())\nscoreboard = json.loads((RUN / 'scoreboard.json').read_text())['scores']\nretrieval = json.loads((ROOT / 'base/retrieval_results.json').read_text())\nassert len(rows) == 3 * manifest['n_cases']\nassert len({r['case_id'] for r in rows}) == manifest['n_cases']\nfor s in scoreboard:\n    subset = [r for r in rows if r['configuration'] == s['configuration']]\n    assert s['property_correct'] == sum(r['automatic']['property_correct'] for r in subset)\n    display(Markdown(f\"**{s['configuration']}**: {s['property_correct']}/{s['n']} casos aprovados por propriedades; JSON final {s['final_json_valid']}/{s['n']}; geração bruta válida {s['model_json_valid']}/{s['model_calls']} chamadas.\"))\ndisplay(Markdown(f\"Recuperação: recall@1 = **{retrieval['test']['recall_at_1']:.1%}**; recall@3 = **{retrieval['test']['recall_at_3']:.1%}**, sobre {retrieval['test']['n_answerable']} perguntas respondíveis.\"))"),
      md('## Contexto e método\n\n**Tarefa:** reduzir a incerteza de quem espera ônibus municipais em São Paulo por meio de respostas verificáveis, esclarecimento de ambiguidades e recusa quando faltar suporte. Não foi medida redução efetiva de espera.\n\nA rubrica usa “treinamento” e aceita especialização por LoRA ou agente. Aqui não houve ajuste de pesos: o agente acrescenta ferramentas controladas e validação à LLM local. A composição A/B/C interpreta a exigência de três configurações em conjunto com a comparação ao modelo sem contexto.\n\n### Premissas e limites\n\n- Mesmo modelo e parâmetros de geração; as fontes e ferramentas variam conforme a configuração.\n- Conjuntos DEV/TEST separados e hashes congelados; TEST não pode orientar ajuste.\n- Casos dinâmicos são fixtures sintéticas versionadas; integração SPTrans real requer evidência separada.\n- Amostra pequena e autoral, sem representatividade estatística da população.\n- Guardrails podem melhorar o sistema final sem melhorar os pesos ou a geração bruta.\n- Latência foi observada localmente, sem significar SLA em Cloud.'),
      code("display(Markdown(f\"**Início UTC:** {manifest['started_at']}  \\n**Fim UTC:** {manifest.get('finished_at')}  \\n**Casos por configuração:** {manifest['n_cases']}  \\n**Modelo observado:** {', '.join(manifest['models_observed'])}  \\n**Código/base inalterados durante a execução:** {manifest['code_unchanged_during_run']}  \\n**Hash do conjunto:** `{manifest['dataset_sha256']}`\"))"),
      md('## Dados e critérios\n\nAs evidências completas estão em `responses.jsonl` no diretório da execução. Cada linha preserva entrada, saída final, geração bruta, duração e critérios. `base/chunks.jsonl` contém textos, fonte e data. Os testes/gabaritos são `avaliacao/test.jsonl`; o manifesto de congelamento é `avaliacao/freeze.json`.\n\n**Acerto por propriedades:** status aceito, JSON final válido, fatos obrigatórios presentes, sem candidato a afirmação proibida e fonte quando exigida. **Recusa/estado negativo:** estado correto nos casos sem resposta suportada (inclui esclarecimento e indisponibilidade). **Alucinação:** afirmação factual não sustentada, analisada separadamente; um erro de formato ou uma omissão não é automaticamente alucinação.'),
      code("headers = ['Configuração','Casos','Propriedades','JSON final','Fontes','Recusa/status negativo','JSON bruto','Latência média (s)']\nlines = ['| ' + ' | '.join(headers) + ' |', '|'+ '|'.join(['---']*len(headers))+'|']\nfor s in scoreboard:\n    values = [s['configuration'],str(s['n']),f\"{s['property_correct']}/{s['n']}\",f\"{s['final_json_valid']}/{s['n']}\",f\"{s['sources_present']}/{s['source_n']}\",f\"{s['refusal_correct']}/{s['refusal_n']}\",f\"{s['model_json_valid']}/{s['model_calls']}\",str(s['mean_latency_seconds'])]\n    lines.append('| ' + ' | '.join(values) + ' |')\ndisplay(Markdown('\\n'.join(lines)))"),
      md('## Comparação das configurações\n\nCada barra usa os mesmos casos. Valores ausentes não foram transformados em zero. O eixo começa em zero; rótulos mostram contagens e denominadores.'),
      code("plt.rcParams.update({'font.size': 11, 'axes.titlesize': 14, 'axes.labelsize': 11, 'figure.dpi': 130})\nlabels = ['Sem contexto', 'RAG simples', 'RAG + agente']\ncolors = ['#52647D', '#218C9C', '#173E66']\nfig, axes = plt.subplots(1, 2, figsize=(11, 4.5), layout='constrained')\nfor ax, metric, title in [(axes[0], 'property_correct', 'Acerto por propriedades'), (axes[1], 'status_correct', 'Status correto')]:\n    values = [s[metric] / s['n'] for s in scoreboard]\n    bars = ax.bar(labels, values, color=colors, width=.65)\n    ax.set_ylim(0, 1.12); ax.set_yticks([0,.25,.5,.75,1], ['0%','25%','50%','75%','100%'])\n    ax.set_title(title); ax.set_ylabel('Proporção dos casos'); ax.grid(axis='y', alpha=.2); ax.set_axisbelow(True)\n    for bar,s in zip(bars,scoreboard): ax.text(bar.get_x()+bar.get_width()/2,bar.get_height()+.025,f\"{s[metric]}/{s['n']}\",ha='center',weight='bold')\nfig.suptitle('Ponto Certo · mesmo modelo, três configurações', fontsize=16)\nfig.savefig(ROOT / 'notebooks/placar.png', bbox_inches='tight')\nplt.show()"),
      md('## Recuperação e limiar\n\nRecall@k é a média de `|relevantes ∩ top-k| / |relevantes|` entre perguntas respondíveis. Como há um trecho relevante por pergunta neste conjunto, coincide com hit@k. O limiar foi escolhido apenas em DEV, pela acurácia balanceada entre aceitar respondíveis e rejeitar negativos; empates priorizam recall após o filtro e depois limiar menor.'),
      code("r = retrieval['test']\ndisplay(Markdown(f\"**Limiar escolhido:** {retrieval['selected_threshold']:.2f}. Grade DEV 0,05–0,50. Scores cosseno não são probabilidades.  \\n**Recall@1:** {r['recall_at_1']:.1%}; **recall@3:** {r['recall_at_3']:.1%}; após filtro: {r['accepted_recall_at_3']:.1%}.  \\n**Negativos rejeitados:** {round(r['unanswerable_rejection_rate'] * r['n_unanswerable'])}/{r['n_unanswerable']}.  \\n**Denominadores:** {r['n_answerable']} respondíveis + {r['n_unanswerable']} sem resposta.\"))\nfailed = [x for x in r['details'] if x['recall_at_1'] is not None and x['recall_at_1'] < 1]\nfor x in failed: display(Markdown(f\"- {x['id']}: {x['question']} — relevante `{x['relevant_ids']}`, top-1 `{x['ranked'][0]['id']}`.\"))"),
      md('## Erros observados e interpretação\n\nO arquivo de auditoria registra a distinção entre erro, omissão e alucinação. As causas descritas são hipóteses técnicas, não diagnóstico comprovado de mecanismo interno do modelo. Propostas de correção não foram contabilizadas como desempenho já obtido.'),
      code("audit_path = RUN / 'audit.json'\nif audit_path.exists():\n    audit = json.loads(audit_path.read_text())\n    display(Markdown(audit.get('summary','')))\n    for error in audit.get('five_errors',[]):\n        display(Markdown(f\"### {error['case_id']} · {error['configuration']}\\n**Entrada:** {error['question']}\\n\\n**Resposta observada:** {error['answer']}\\n\\n**Esperado:** {error['expected']}\\n\\n**Causa provável:** {error['probable_cause']}\\n\\n**Correção proposta:** {error['proposed_fix']}\"))\nelse:\n    display(Markdown('**Auditoria semântica ainda não disponível.** Não inferir taxa de alucinação dos candidatos automáticos.'))"),
      md('## Conclusão e reprodução\n\nO experimento permite avaliar o ganho da recuperação e do agente no conjunto documentado. Não prova cobertura municipal integral, confiabilidade em toda pergunta ou redução de tempo de espera. A comprovação da publicação e de integração ao vivo pertence às evidências de execução correspondentes.\n\n**Reexecutar inferência:** seguir o README principal para subir o mesmo modelo; executar `python -m avaliacao.run --split test --output avaliacao/runs/test-nova-versao`. Isso cria uma réplica, não um novo conjunto cego.\n\n**Reexecutar este notebook:** instalar `notebooks/requirements.txt` e executar de cima para baixo. As saídas salvas são recalculadas a partir dos JSON versionados, sem novas chamadas ao modelo.\n\n**Fontes:** PDF oficial p28–31; documentação oficial SPTrans vinculada em cada trecho; fixtures identificadas em `dados/fixtures/`; arquivos de casos, respostas e manifests referidos acima.')
    ]
    path=ROOT/'notebooks/avaliacao-ia.ipynb'
    NotebookClient(n,timeout=120,kernel_name='python3',resources={'metadata':{'path':str(ROOT)}}).execute()
    nbformat.validate(n)
    nbformat.write(n,path)
    html,_=HTMLExporter().from_notebook_node(n)
    (ROOT/'notebooks/avaliacao-ia.html').write_text(html)
    print(path)
if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--run',default='avaliacao/runs/test-v1');main(parser.parse_args())
